/** Return the container-less artwork used on agent profile covers. */
export function getUnmaskedAgentAvatarSrc(src: string): string {
	const match = src.match(/^\/avatar-agent-new\/(blue|lime|orange|purple|yellow)\/([^/]+\.svg)$/u);
	if (match) return `/avatar-agent-new-unmasked/${match[1]}/${match[2]}`;
	return src.startsWith("/avatar-agent/") ? src.replace("/avatar-agent/", "/avatar-agent-unmasked/") : src;
}

export function migrateAgentAvatarSrc(src: string | undefined): string | undefined {
	return src ? LEGACY_AGENT_AVATARS[src] ?? src : src;
}


const FALLBACK_AVATAR_SRC: AgentAvatarSrc = AGENT_AVATAR_SRCS[0];
export const DEFAULT_AGENT_PROFILE_AVATAR_SRC = "/avatar-agent-new/blue/backlog-buddy.svg" satisfies AgentAvatarSrc;

/**
 * Returns the family group segment (e.g. "teamwork-agents") for an avatar path,
 * or `undefined` if the path doesn't match the expected shape.
 */
function getAgentAvatarGroup(avatarSrc: string): string | undefined {
	return avatarSrc.match(/\/avatar-agent(?:-new)?\/([^/]+)\//u)?.[1];
}

/**
 * Returns the brand accent color for an avatar, derived from its family group in
 * the path. Falls back to the default accent for unrecognized paths.
 */
export function getAgentAvatarAccent(avatarSrc: string): string {
	const group = getAgentAvatarGroup(avatarSrc);
	return (group && AGENT_AVATAR_GROUP_ACCENTS[group]) || AGENT_AVATAR_FALLBACK_ACCENT;
}

// Avatars bucketed by family group, so a random pick can weight each color
// equally regardless of how many avatars a given color ships.
const AGENT_AVATAR_SRCS_BY_GROUP: ReadonlyArray<ReadonlyArray<AgentAvatarSrc>> = (() => {
	const groups = new Map<string, AgentAvatarSrc[]>();
	for (const src of AGENT_AVATAR_SRCS) {
		const group = getAgentAvatarGroup(src) ?? "";
		const bucket = groups.get(group);
		if (bucket) {
			bucket.push(src);
		} else {
			groups.set(group, [src]);
		}
	}
	return [...groups.values()];
})();

/**
 * Picks a random avatar with the color (family) chosen uniformly first, then a
 * uniformly random avatar within that family. This gives every brand color an
 * equal chance if the number of designs differs between colors.
 */
export function getRandomAgentAvatarSrc(): AgentAvatarSrc {
	const groupIndex = Math.floor(Math.random() * AGENT_AVATAR_SRCS_BY_GROUP.length);
	const group = AGENT_AVATAR_SRCS_BY_GROUP[groupIndex];
	if (!group || group.length === 0) {
		return FALLBACK_AVATAR_SRC;
	}
	const avatarIndex = Math.floor(Math.random() * group.length);
	return group[avatarIndex] ?? FALLBACK_AVATAR_SRC;
}

// Stable 32-bit string hash (FNV-1a). Used to derive a deterministic avatar from
// an agent's identity so two surfaces that independently render the same agent
// (the streamed result card and the persisted session entry) land on the exact
// same avatar — and therefore the same banner color — without sharing state.
function hashSeed(seed: string): number {
	let hash = 0x811c9dc5;
	for (let index = 0; index < seed.length; index += 1) {
		hash ^= seed.charCodeAt(index);
		hash = Math.imul(hash, 0x01000193);
	}
	return hash >>> 0;
}

/**
 * Deterministic counterpart to {@link getRandomAgentAvatarSrc}: the same `seed`
 * (typically an agent's `agentId`) always returns the same avatar, while still
 * balancing the choice by color family first so no single brand color dominates.
 *
 * Use this — not the random picker — whenever an agent that lacks an explicit
 * avatar is rendered in more than one place, so every surface agrees on the
 * avatar (and the family-derived banner color) for that identity. An empty seed
 * falls back to a stable default.
 */
export function getDeterministicAgentAvatarSrc(seed: string | null | undefined): AgentAvatarSrc {
	const normalizedSeed = seed?.trim();
	if (!normalizedSeed) {
		return FALLBACK_AVATAR_SRC;
	}
	const hash = hashSeed(normalizedSeed);
	const group = AGENT_AVATAR_SRCS_BY_GROUP[hash % AGENT_AVATAR_SRCS_BY_GROUP.length];
	if (!group || group.length === 0) {
		return FALLBACK_AVATAR_SRC;
	}
	// A second, independent shift keeps the within-family pick from correlating
	// with the family pick for short seeds.
	const avatarIndex = (hash >>> 8) % group.length;
	return group[avatarIndex] ?? FALLBACK_AVATAR_SRC;
}

